#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
static double now(){ struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts); return ts.tv_sec + ts.tv_nsec/1e9; }
int main(){
    size_t n = 40960000;
    char *a = malloc(n), *b = malloc(n);
    memset(a, 1, n);
    // warm
    memcpy(b, a, n);
    double t0=now();
    for(int i=0;i<10;i++) memcpy(b, a, n);
    double t1=now();
    printf("memcpy 40MB x10: %.4f s -> %.2f GB/s (read+write)\n", t1-t0, n*10/(t1-t0)/1e9);
    // memset
    t0=now();
    for(int i=0;i<10;i++) memset(b, 0, n);
    t1=now();
    printf("memset 40MB x10: %.4f s -> %.2f GB/s (write)\n", t1-t0, n*10/(t1-t0)/1e9);
    return 0;
}
