{"command":"cd /private/var/folders/bd/8xxg4c4j4rqc_6fqwvpxwnd80000gn/T/algotuneprobe_74ksdteh/ep0; cat > bw.c <<'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
static double now(){ struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts); return ts.tv_sec + ts.tv_nsec/1e9; }
int main(){
    size_t n = 40960000;
    char *a = malloc(n), *b = malloc(n);
    memset(a, 1, n); memset(b, 2, n);
    volatile unsigned long long sink = 0;
    // warm
    memcpy(b, a, n);
    double t0=now();
    for(int i=0;i<20;i++){ memcpy(b, a, n); sink += (unsigned char)b[0]; }
    double t1=now();
    printf("memcpy 40MB x20: %.4f s -> %.2f GB/s (read+write)\n", t1-t0, n*20.0/(t1-t0)/1e9);
    // memset
    t0=now();
    for(int i=0;i<20;i++){ memset(b, 0, n); sink += (unsigned char)b[0]; }
    t1=now();
    printf("memset 40MB x20: %.4f s -> %.2f GB/s (write only)\n", t1-t0, n*20.0/(t1-t0)/1e9);
    printf("sink=%llu\n", sink);
    return 0;
}
EOF
gcc -O2 bw.c -o bw 2>/dev/null && ./bw"}

